#!/usr/bin/env bash
# shellcheck disable=SC1003,SC2016
# @covers AC-CI-ONBOARDING-001
# @covers AC-BAUTH-005, AC-BAUTH-008
# @spec: ci-cd-pipeline_spec.md
# @runtime-dependencies: none
#
# Verify that cold-start onboarding docs, setup scripts, and the heavy bootstrap
# workflow stay aligned.
set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
cd "$REPO_ROOT"

FAILURES=()

fail() {
  printf 'FAIL: %s\n' "$1" >&2
  FAILURES+=("$1")
}

pass() {
  printf 'PASS: %s\n' "$1"
}

require_file() {
  local path="$1"
  if [[ -e "$path" ]]; then
    pass "required path exists: $path"
  else
    fail "required path is missing: $path"
  fi
}

require_executable() {
  local path="$1"
  if [[ -x "$path" ]]; then
    pass "required script is executable: $path"
  else
    fail "required script is not executable: $path"
  fi
}

require_contains() {
  local path="$1"
  local pattern="$2"
  local label="$3"
  if rg -q -- "$pattern" "$path"; then
    pass "$label"
  else
    fail "$label"
  fi
}

reject_contains() {
  local path="$1"
  local pattern="$2"
  local label="$3"
  if rg -q -- "$pattern" "$path"; then
    fail "$label"
  else
    pass "$label"
  fi
}

require_line_count() {
  local path="$1"
  local pattern="$2"
  local expected="$3"
  local label="$4"
  local count

  count="$({ rg -n -- "$pattern" "$path" || true; } | wc -l | tr -d ' ')"
  if [[ "$count" == "$expected" ]]; then
    pass "$label"
  else
    fail "$label (expected $expected, found $count)"
  fi
}

require_target_contains() {
  local path="$1"
  local target="$2"
  local literal="$3"
  local label="$4"

  if awk -v target="$target" -v literal="$literal" '
    $0 ~ "^target \"" target "\"[[:space:]]*\\{" { in_target = 1 }
    in_target && index($0, literal) { found = 1; exit }
    in_target && $0 ~ "^target \"" && $0 !~ "^target \"" target "\"[[:space:]]*\\{" { exit }
    END { exit found ? 0 : 1 }
  ' "$path"; then
    pass "$label"
  else
    fail "$label"
  fi
}

